mapper.select:
SELECT * FROM question
WHERE category_level = #{categoryLevel}
AND COALESCE(audit_status, 'approved') = 'approved'
AND COALESCE(status, 1) = 1

    AND subject_name = #{subjectName}


    AND question_type = #{questionType}

ORDER BY RAND()
LIMIT #{limit}

SELECT * FROM question
WHERE created_by = #{userId}
AND COALESCE(audit_status, 'approved') = 'approved'
AND COALESCE(status, 1) = 1

    AND category_level = #{categoryLevel}


    AND subject_name = #{subjectName}


    AND question_type = #{questionType}


    AND difficulty_level = #{difficultyLevel}


    AND knowledge_point LIKE CONCAT('%', #{knowledgePoint}, '%')

ORDER BY RAND()
LIMIT #{limit}

mapper.update:
UPDATE question
SET use_count = use_count + 1
WHERE id = #{id}

mapper.select:
SELECT ar.*, qb.question_title, qb.answer_analysis
FROM answer_record ar
LEFT JOIN question qb ON ar.question_id = qb.id
WHERE 1=1

    AND ar.user_id = #{userId}


    AND ar.subject_name = #{subjectName}


    AND ar.question_type = #{questionType}


    AND ar.is_correct = #{isCorrect}


    AND ar.knowledge_point = #{knowledgePoint}


    AND ar.answer_at >= #{startDate}


    AND ar.answer_at <= #{endDate}

ORDER BY ar.answer_at DESC, ar.created_at DESC
LIMIT #{offset}, #{pageSize}
